mapper.update:
update moving_order
order_status = #{orderStatus}, is_paid = #{isPaid}, payment_time = #{paymentTime}, pay_method = #{payMethod}, cancel_reason = #{cancelReason}, cancel_time = #{cancelTime}, moving_start_time = #{movingStartTime}, moving_end_time = #{movingEndTime}, driver_id = #{driverId}, vehicle_id = #{vehicleId}, is_reviewed = #{isReviewed}, update_time = #{updateTime},
where id = #{id}

mapper.select:
select mo.id as order_id, mo.customer_id, mo.order_number, mo.service_id, mo.truck_type_id, mo.driver_id, mo.vehicle_id, mo.order_status, mo.reservation_time, mo.moving_origin, mo.moving_destination, mo.moving_price, mo.mileage_cost, mo.helper_cost, mo.category_price_multiplier, mo.is_paid, mo.payment_time, mo.pay_method, mo.cancel_reason, mo.cancel_time, mo.moving_start_time, mo.moving_end_time, mo.number_of_helpers, mo.notes, mo.is_reviewed, mo.create_time, mo.update_time, s.service_name, tt.type_name as truck_type_name from moving_order mo join service s on mo.service_id = s.id join truck_type tt on mo.truck_type_id = tt.id
mo.customer_id = #{userId}
and mo.order_status = #{orderStatus}
order by mo.create_time desc

SELECT mo.id as order_id, mo.customer_id, mo.order_number, mo.service_id, mo.truck_type_id, mo.driver_id, mo.vehicle_id, mo.order_status, mo.reservation_time, mo.moving_origin, mo.moving_destination, mo.moving_price, mo.mileage_cost, mo.helper_cost, mo.category_price_multiplier, mo.is_paid, mo.payment_time, mo.pay_method, mo.cancel_reason, mo.cancel_time, mo.moving_start_time, mo.moving_end_time, mo.number_of_helpers, mo.notes, mo.is_reviewed, mo.create_time, mo.update_time,
c.name as customer_name, c.phone as customer_phone, s.service_name, sc.type_name as category_name, tt.type_name as truck_type_name,
d.name as driver_name, v.license_plate_number as vehicle_plate, d.phone as driver_phone FROM moving_order mo JOIN customer c ON mo.customer_id = c.id JOIN service s ON mo.service_id = s.id JOIN truck_type tt ON mo.truck_type_id = tt.id JOIN service_category sc ON s.category_id = sc.id LEFT JOIN driver d ON mo.driver_id = d.id LEFT JOIN vehicle v ON mo.vehicle_id = v.id
AND mo.order_number LIKE CONCAT('%', #{orderNumber}, '%')
AND mo.order_status = #{orderStatus}
AND mo.is_paid = #{isPaid}
AND mo.create_time >= #{createTimeStart}
AND mo.create_time <= #{createTimeEnd}
AND (c.name LIKE CONCAT('%', #{customerKeyword}, '%') OR c.phone LIKE CONCAT('%', #{customerKeyword}, '%'))
AND d.name LIKE CONCAT('%', #{driverName}, '%')
AND s.service_name LIKE CONCAT('%', #{serviceItemName}, '%')
AND s.category_id = #{categoryId}
AND mo.truck_type_id = #{truckTypeId}
AND mo.reservation_time >= #{reservationTimeStart}
AND mo.reservation_time <= #{reservationTimeEnd}
ORDER BY mo.create_time DESC

SELECT mo.id, mo.order_number, mo.truck_type_id,
mo.moving_origin, mo.moving_destination,
mo.reservation_time, mo.moving_price, mo.number_of_helpers,
tt.type_name, tt.capacity
FROM moving_order mo
JOIN truck_type tt ON mo.truck_type_id = tt.id
LEFT JOIN service s ON mo.service_id = s.id
LEFT JOIN service_category sc ON s.category_id = sc.id
WHERE
mo.order_status = 0 AND mo.is_paid = 1 AND mo.truck_type_id IN (
SELECT truck_type_id
FROM driver_truck_type
WHERE driver_id = #{currentDriverId}
)

    AND mo.reservation_time BETWEEN #{dto.startDate} AND #{dto.endDate}


    AND mo.reservation_time >= #{dto.startDate}


    AND mo.reservation_time <= #{dto.endDate}


    AND mo.truck_type_id = #{dto.truckTypeId}


    AND sc.id = #{dto.serviceCategoryId}

ORDER BY mo.reservation_time ASC
